WITH joined AS (SELECT a.*, p.region, p.store_name FROM orders a LEFT JOIN stores p ON a.store_id = p.id), kept AS (SELECT s.* FROM joined s WHERE EXISTS (SELECT 1 FROM payments x WHERE x.order_id = s.id AND x.paid_at <= s.order_date)), enriched AS (SELECT s.*, d.store_name AS store_store_name, d.city, d.sqft FROM kept s INNER JOIN stores d ON s.store_id = d.id), latest_match AS (SELECT s.*, x.quantity, x.unit_price FROM enriched s LEFT JOIN LATERAL (SELECT c.quantity, c.unit_price FROM order_items c WHERE c.order_id = s.id ORDER BY c.quantity DESC, c.id DESC LIMIT 1) x ON TRUE), with_windows AS (SELECT *, AVG(quantity) OVER (PARTITION BY customer_id) AS customer_id_avg_quantity, LEAD(discount, 2) OVER (ORDER BY shipping_fee, id) AS next_discount, ROUND(amount / SUM(amount) OVER (PARTITION BY channel), 4) AS amount_share, RANK() OVER w_running AS quantity_rank, SUM(sqft) OVER (PARTITION BY region ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sqft FROM latest_match WINDOW w_running AS (PARTITION BY customer_id ORDER BY quantity DESC NULLS LAST)), with_windows_orders AS (SELECT *, RANK() OVER (PARTITION BY channel ORDER BY quantity DESC) AS quantity_rank_2, AVG(sqft) OVER (PARTITION BY city ORDER BY sqft, id ROWS BETWEEN 5 PRECEDING AND 1 PRECEDING) AS sqft_avg_5_prior, AVG(amount_share) OVER (PARTITION BY customer_id, channel) AS customer_id_avg_amount_share FROM with_windows) SELECT id, customer_id, store_id, order_date, status, channel, discount, region, store_name FROM with_windows_orders ORDER BY customer_id
